const words = ["skyscraper", "chair", "umbrella", "curtain"];

// Function to calculate word length
function getWordLength(word) {
    return word.length;
}

// Create an array of objects with word and length properties
const wordData = words.map((word) => ({
    word,
    length: getWordLength(word)
}));

// Sort the array based on the length property
wordData.sort((a, b) => a.length - b.length);

console.log(JSON.stringify(wordData));
```

